module fix_retry_rearm(
    input       clk,
    input       rst_n,
    input       req,
    input       resp,
    output reg   out_req,
    output reg   ok,
    output reg   fail,
    output reg [1:0] tries
);
    reg [1:0] win;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out_req <= 1'b0; ok <= 1'b0; fail <= 1'b0;
            tries   <= 2'd0; win <= 2'd0;
        end else begin
            ok <= 1'b0;
            if (!out_req && !fail) begin
                if (req) begin
                    out_req <= 1'b1; win <= 2'd0; tries <= 2'd0; fail <= 1'b0;
                end
            end else if (resp) begin
                out_req <= 1'b0; ok <= 1'b1; win <= 2'd0; tries <= 2'd0;
            end else if (win == 2'd2) begin
                win   <= 2'd0;
                tries <= 2'd0;  // suspect line: expiry wipes the attempt history
            end else begin
                win <= win + 2'd1;
            end
        end
    end
endmodule

module fix_skid_drop(
    input       clk,
    input       rst_n,
    input       in_valid,
    input  [7:0] in_data,
    input       out_rdy,
    output       in_ready,
    output reg   out_valid,
    output reg [7:0] out_data
);
    reg       s1_v, s2_v;
    reg [7:0] s1_d, s2_d;

    assign in_ready = !s1_v || !s2_v || out_rdy;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            s1_v <= 1'b0; s2_v <= 1'b0;
            s1_d <= 8'd0; s2_d <= 8'd0;
        end else begin
            if (!s2_v) begin        // suspect line: stage two never reloads
                s2_v <= s1_v;       // when the consumer is taking its item
                s2_d <= s1_d;
            end
            if (in_ready) begin
                s1_v <= in_valid;
                s1_d <= in_data;
            end
        end
    end

    assign out_valid = s2_v;
    assign out_data  = s2_d;
endmodule

module fix_dma_ptr_reset(
    input       clk,
    input       rst_n,
    input       start,
    input  [3:0] len,
    input  [3:0] base,
    output reg   busy,
    output reg   done,
    output reg [3:0] addr,
    output reg [3:0] ptr
);
    reg [2:0] bcnt;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            busy <= 1'b0; done <= 1'b0;
            addr <= 4'd0; ptr <= 4'd0; bcnt <= 3'd0;
        end else begin
            done <= 1'b0;
            if (!busy) begin
                if (start && len != 4'd0) begin
                    busy <= 1'b1;
                    bcnt <= 3'd1;
                    addr <= base;
                    ptr  <= 4'd1;
                end
            end else begin
                addr <= base + ptr;
                ptr  <= ptr + 4'd1;
                bcnt <= bcnt + 3'd1;
                if (bcnt + 3'd1 == len) begin
                    done <= 1'b1;
                    busy <= 1'b0;
                    // suspect line: ptr is left at len, never cleared
                end
            end
        end
    end
endmodule

module fix_cache_dirty_wb(
    input       clk,
    input       rst_n,
    input       wr,
    input  [5:0] addr,
    input  [7:0] wdata,
    input       rd,
    output reg [7:0] rdata,
    output reg   hit,
    output reg   miss,
    output reg   evict,
    output reg   wb
);
    reg        valid [0:3];
    reg [1:0]  tag   [0:3];
    reg        dirty [0:3];
    reg [7:0]  data  [0:3];

    wire [1:0] idx = addr[3:2];
    wire [1:0] tg  = addr[5:4];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            hit <= 1'b0; miss <= 1'b0; evict <= 1'b0; wb <= 1'b0; rdata <= 8'd0;
        end else begin
            hit <= 1'b0; miss <= 1'b0; evict <= 1'b0; wb <= 1'b0;
            if (wr) begin
                if (valid[idx] && tag[idx] != tg) begin
                    evict <= 1'b1;
                    wb    <= 1'b1;   // suspect line: writebacks every eviction
                end
                valid[idx] <= 1'b1;
                tag[idx]   <= tg;
                data[idx]  <= wdata;
                dirty[idx] <= 1'b1;
            end else if (rd) begin
                if (valid[idx] && tag[idx] == tg) begin
                    hit   <= 1'b1;
                    rdata <= data[idx];
                end else begin
                    miss        <= 1'b1;
                    rdata       <= 8'd0;
                    valid[idx]  <= 1'b1;
                    tag[idx]    <= tg;
                    data[idx]   <= 8'd0;
                    dirty[idx]  <= 1'b0;  // suspect area: dirty never consulted
                end
            end
        end
    end
endmodule

module fix_bucket_refill_order(
    input       clk,
    input       rst_n,
    input       req,
    input  [1:0] rate,
    output reg   grant,
    output reg   deny,
    output reg [2:0] tokens
);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tokens <= 3'd0; grant <= 1'b0; deny <= 1'b0;
        end else begin
            grant <= 1'b0;
            deny  <= 1'b0;
            if (req && tokens != 3'd0) begin   // suspect line: pre-refill test
                grant  <= 1'b1;
                tokens <= tokens - 3'd1 + {1'b0, rate};
            end else if (req) begin
                deny   <= 1'b1;
                tokens <= tokens + {1'b0, rate};
            end else begin
                tokens <= tokens + {1'b0, rate};
            end
        end
    end
endmodule

module fix_interleaver_align(
    input       clk,
    input       rst_n,
    input       wr,
    input  [7:0] din,
    input       rd,
    output reg [7:0] dout,
    output reg   dv,
    output reg [2:0] count
);
    reg [7:0] mem [0:3];
    reg [1:0] wptr;
    reg [1:0] rptr;   // column-major position

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= 3'd0; dout <= 8'd0; dv <= 1'b0;
            wptr  <= 2'd0;
            rptr  <= 2'd1;   // suspect line: should start at cell 0
        end else begin
            dv <= 1'b0;
            if (wr && count < 3'd4) begin
                mem[wptr] <= din;
                wptr <= wptr + 2'd1;
                count <= count + 3'd1;
            end else if (rd && count == 3'd4) begin
                dout <= mem[rptr];
                dv   <= 1'b1;
                count <= count - 3'd1;
                rptr <= (rptr == 2'd1) ? 2'd2 :
                        (rptr == 2'd2) ? 2'd0 : 2'd1;
            end
        end
    end
endmodule

module fix_burst_tail(
    input       clk,
    input       rst_n,
    input       start,
    input  [3:0] len,
    input       beat,
    output reg   busy,
    output reg   chunk_done,
    output reg   last_chunk,
    output reg [2:0] bcnt,
    output reg [3:0] total
);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            busy <= 1'b0; chunk_done <= 1'b0; last_chunk <= 1'b0;
            bcnt <= 3'd0; total <= 4'd0;
        end else begin
            chunk_done <= 1'b0;
            last_chunk <= 1'b0;
            if (!busy) begin
                if (start && len != 4'd0) begin
                    busy <= 1'b1; bcnt <= 3'd0; total <= 4'd0;
                end
            end else if (beat) begin
                total <= total + 4'd1;
                if (bcnt == 3'd4) begin
                    bcnt       <= 3'd0;
                    chunk_done <= 1'b1;
                end else begin
                    bcnt <= bcnt + 3'd1;
                    // suspect area: the 1-to-3 beat tail never completes
                end
                if (total + 4'd1 == len) begin
                    busy <= 1'b0;
                end
            end
        end
    end
endmodule

module fix_movavg_tap(
    input       clk,
    input       rst_n,
    input       en,
    input  [7:0] sample,
    output [9:0] sum,
    output [7:0] avg,
    output [1:0] wptr
);
    reg [9:0] sum_r;
    reg [7:0] buf [0:3];
    reg [1:0] ptr;

    wire [1:0] old = (ptr == 2'd0) ? 2'd3 : ptr - 2'd1;  // suspect line

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum_r <= 10'd0; ptr <= 2'd0;
        end else if (en) begin
            sum_r    <= sum_r + {2'b0, sample} - {2'b0, buf[old]};
            buf[ptr] <= sample;
            ptr      <= ptr + 2'd1;
        end
    end

    assign sum   = sum_r;
    assign avg   = sum_r[9:2];
    assign wptr  = ptr;
endmodule

